package com.gamehub.application;
import com.gamehub.domain.*; import com.gamehub.infrastructure.Database; import java.security.*; import javax.crypto.SecretKeyFactory; import java.sql.*; import java.util.Base64;
public final class UserService { private final Database db; public UserService(Database db){this.db=db;}
 public void bootstrap(String username,String password)throws Exception{validate(username,password);try(var q=db.connection().prepareStatement("SELECT COUNT(*) FROM users");var r=q.executeQuery()){if(r.next()&&r.getInt(1)>0)throw new IllegalStateException("Manager already configured");} insert(username,password,"MANAGER");}
 public User registerCustomer(String username,String password)throws Exception{validate(username,password);insert(username,password,"CUSTOMER"); User u=authenticate(username,password); try(var p=db.connection().prepareStatement("INSERT INTO customers(user_id,full_name,created_at) VALUES(?,?,?)")){p.setLong(1,u.id());p.setString(2,username.trim());p.setString(3,java.time.Instant.now().toString());p.executeUpdate();} return u;}
 public User registerCustomer(String fullName,String email,String phone,String password)throws Exception{if(fullName==null||fullName.isBlank()||email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||phone==null||!phone.matches("^[+0-9][0-9 ()-]{6,}$"))throw new IllegalArgumentException("Full name, valid email and phone are required");String login=email.trim().toLowerCase(java.util.Locale.ROOT);validate(login,password);Connection c=db.connection();c.setAutoCommit(false);try{insert(login,password,"CUSTOMER");long id;try(var q=c.prepareStatement("SELECT id FROM users WHERE username=?")){q.setString(1,login);try(var r=q.executeQuery()){if(!r.next())throw new SQLException("Created user was not found");id=r.getLong(1);}}try(var p=c.prepareStatement("INSERT INTO customers(user_id,full_name,email,phone,created_at) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setString(2,fullName.trim());p.setString(3,login);p.setString(4,phone.trim());p.setString(5,java.time.Instant.now().toString());p.executeUpdate();}c.commit();return new User(id,login,Role.CUSTOMER);}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
 public User provision(String actorUsername,String password,String username,String temporaryPassword,Role role)throws Exception{User actor=authenticate(actorUsername,password);if(actor==null||actor.role()!=Role.MANAGER)throw new SecurityException("Manager authentication required");if(role==Role.CUSTOMER)throw new IllegalArgumentException("Use customer registration for public accounts");validate(username,temporaryPassword);insert(username,temporaryPassword,role.name());return authenticate(username,temporaryPassword);}
 private void insert(String u,String p,String role)throws Exception{try(var s=db.connection().prepareStatement("INSERT INTO users(username,password_hash,role,created_at) VALUES(?,?,?,?)")){s.setString(1,u);s.setString(2,hash(p));s.setString(3,role);s.setString(4,java.time.Instant.now().toString());s.executeUpdate();}}
 private static void validate(String u,String p){if(u.isBlank()||p.length()<8)throw new IllegalArgumentException("Username and password (8+ characters) are required");}
 public User authenticate(String username,String password)throws SQLException{try(var p=db.connection().prepareStatement("SELECT id,username,role,password_hash FROM users WHERE username=? AND active=1")){p.setString(1,username==null?"":username.trim().toLowerCase(java.util.Locale.ROOT));try(var r=p.executeQuery()){if(!r.next()||!verify(password,r.getString(4)))return null;return new User(r.getLong(1),r.getString(2),Role.valueOf(r.getString(3)));}}}
 private static String hash(String s)throws Exception{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(pbkdf(s,salt));}
 private static boolean verify(String s,String stored){try{String[] x=stored.split(":");return MessageDigest.isEqual(pbkdf(s,Base64.getDecoder().decode(x[0])),Base64.getDecoder().decode(x[1]));}catch(Exception e){return false;}}
 private static byte[] pbkdf(String s,byte[] salt)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new javax.crypto.spec.PBEKeySpec(s.toCharArray(),salt,120000,256)).getEncoded();}}
